`,e.jsxs(h,{tab:"Loss Spikes & Stability",plate:"siemienowicz-rocket-barrel",children:[e.jsxs(i,{title:"Loss spikes have several trajectories and causes",accent:3,number:"35",items:"4",children:[e.jsxs(t.ul,{children:[`
